"""Node catalogue node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory


class NodeCatalogueNode(Node):
    """Give an AI step bounded contracts for available nodes."""

    node_type: ClassVar[str] = 'node_catalogue_node'
    display_name: ClassVar[str] = 'Node catalogue'
    default_alias: ClassVar[str] = 'Node catalogue'
    description: ClassVar[str] = 'Give an AI step bounded contracts for available nodes'
    category: ClassVar[str] = NodeCategory.DATA
    primary_family: ClassVar[str] = 'Utility'
    tags: ClassVar[List[str]] = ['meta', 'workflow']
    icon_name: ClassVar[str] = 'list-check'
    color_hint: ClassVar[str] = 'grey'
    group: ClassVar[Optional[str]] = None
    selector_section: ClassVar[Optional[str]] = 'Transform'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Continue', 'description': 'Sequence this step; incoming data is not a filter.', 'data_type': 'any', 'required': False, 'sources': ['upstream']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Catalogue', 'description': 'Complete matching contracts; errors if over the size cap', 'data_type': 'string', 'required': True, 'to': ['downstream', 'vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'scope': 'All nodes', 'group_filter': 'Any group', 'tag_filter': '', 'search': '', 'detail': 'Compact', 'format': 'Text', 'max_chars': 64000, 'include_debug': False, 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'scope': {'type': 'select', 'label': 'Nodes', 'options': ['All nodes', 'Filtered'], 'tab': 'Parameters'}, 'group_filter': {'type': 'select', 'label': 'Group', 'options': ['Any group', 'AI Processing', 'Branch', 'Data Transform', 'File Reader', 'File Write', 'Hermes', 'Merge', 'Saved values', 'System', 'Text Input', 'Text Output', 'Text files', 'Wait / Timer', 'Web Request'], 'tab': 'Parameters', 'visible_when': {'scope': 'Filtered'}}, 'tag_filter': {'type': 'string', 'label': 'Tag', 'tab': 'Parameters', 'visible_when': {'scope': 'Filtered'}, 'placeholder': 'Any tag'}, 'search': {'type': 'string', 'label': 'Search', 'tab': 'Parameters', 'visible_when': {'scope': 'Filtered'}, 'placeholder': 'Type, name, description or tags'}, 'detail': {'type': 'select', 'label': 'Detail', 'options': ['Brief', 'Compact', 'Detailed'], 'tab': 'Parameters', 'wrap_description': True, 'description': 'Brief: purpose, when to use, not for, effects and needs to shortlist nodes. Then Compact or Detailed, filtered to the chosen nodes, adds full records, ports and config.'}, 'format': {'type': 'select', 'label': 'Output', 'options': ['Text', 'JSON'], 'tab': 'Parameters', 'description': 'Text [string] or a JSON record [var].'}, 'max_chars': {'type': 'integer', 'label': 'Max catalogue (characters)', 'min': 512, 'max': 200000, 'tab': 'Parameters', 'wrap_description': True, 'description': 'Complete output only; narrow filters if the cap is exceeded. Context Pack and model context have separate limits.'}, 'include_debug': {'type': 'boolean', 'label': 'Include debug nodes', 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {'standard_output': True}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'invalid_config', 'description': 'Check catalogue filters and limits.', 'retryable': False}, {'code': 'catalogue_empty', 'description': 'No nodes match. Broaden the filters.', 'retryable': False}, {'code': 'catalogue_too_large', 'description': 'Catalogue is too large. Narrow the filters or raise the cap.', 'retryable': False}]

    @classmethod
    def describe_output_ports(cls, config):
        return {'default': {**cls.output_port_metadata['default'],
                            'data_type': 'var' if config.get('format') == 'JSON' else 'string'}}

    async def execute(self, context: NodeContext) -> None:
        from ...node_factory import NodeFactory
        from ...node_catalogue import build
        from ...meta_workflow import validate_outputs, publish
        from ...node_errors import NodeError
        try:
            validate_outputs(self.config)
            value = await build(NodeFactory(), self.config)
            publish(self.config, context, value, 'var' if self.config['format'] == 'JSON' else 'string')
        except NodeError as exc:
            context.signal_error(exc)
